const currentWeight = parseFloat(
  $('Edit Fields').item.json.weight.replace(/[^\d.]/g, '')
);

let maxWeight = 0;

// If no previous rows exist
if (items.length === 0) {
  return [
    {
      json: {
        currentWeight,
        maxWeight: 0,
        isPR: true
      }
    }
  ];
}

// Check historical rows
for (const item of items) {

  if (!item.json.Weight) continue;

  const weight = parseFloat(
    item.json.Weight.toString().replace(/[^\d.]/g, '')
  );

  if (!isNaN(weight) && weight > maxWeight) {
    maxWeight = weight;
  }
}

return [
  {
    json: {
      currentWeight,
      maxWeight,
      isPR: currentWeight > maxWeight
    }
  }
];

