parameters.jsCode:
const text = $json.text.toLowerCase();

const weightMatch = text.match(/(\d+)\s*kg/i);
const repsMatch = text.match(/(\d+)\s*reps?/i);
const setsMatch = text.match(/(\d+)\s*sets?/i);

let exercise = text
  .replace(/(\d+)\s*kg/i, '')
  .replace(/(\d+)\s*reps?/i, '')
  .replace(/(\d+)\s*sets?/i, '')
  .trim();

return {
  raw_text: text,
  exercise: exercise,
  weight: weightMatch ? parseInt(weightMatch[1]) : null,
  reps: repsMatch ? parseInt(repsMatch[1]) : null,
  sets: setsMatch ? parseInt(setsMatch[1]) : null
};

const exercise = $json.exercise.toLowerCase();

let category = "unknown";

const upper = [
  "inclined",
  "bench",
  "pec deck",
  "machine row",
  "cable pulldown",
  "shoulder press"
];

const lower = [
  "squat",
  "leg press",
  "leg curl",
  "calf raise"
];

const arms = [
  "bicep curl",
  "tricep pushdown",
  "preacher curl"
];

const core = [
  "crunch",
  "cable crunch",
  "plank"
];

if (upper.some(e => exercise.includes(e))) {
  category = "upper";
}

else if (lower.some(e => exercise.includes(e))) {
  category = "lower";
}

else if (arms.some(e => exercise.includes(e))) {
  category = "arms";
}

else if (core.some(e => exercise.includes(e))) {
  category = "core";
}

return {
  ...$json,
  category
};

