// 1. Grab the current incoming workout stats
// Note: Changed to capital letters to match your Google Sheet properties!
const currentExercise = $json.Exercise || $json.exercise;
const currentWeight = parseFloat($json.Weight || 0);
const currentVolume = parseFloat($json.Volume || 0);

let maxWeightHistory = 0;
let maxVolumeHistory = 0;

// 2. Safely look up previous history items
let historyItems = [];
try {
  // This safely grabs data from the node right before this one
  historyItems = $items(); 

  // NOTE: If your Google Sheets node has a specific name like "Google Sheets", 
  // you can uncomment the line below and change it to match your exact node name:
  // historyItems = $items("Google Sheets");
} catch (e) {
  historyItems = [];
}

// 3. Loop through history if any past rows exist
if (Array.isArray(historyItems) && historyItems.length > 0) {
  for (const item of historyItems) {
    // Make sure we only check history matching this exact exercise
    const pastExercise = item.json.Exercise || item.json.exercise;
    if (pastExercise === currentExercise) {
      const pastWeight = parseFloat(item.json.Weight || 0);
      const pastVolume = parseFloat(item.json.Volume || 0);

      if (pastWeight > maxWeightHistory) maxWeightHistory = pastWeight;
      if (pastVolume > maxVolumeHistory) maxVolumeHistory = pastVolume;
    }
  }
}

// 4. Determine if the current workout breaks either record
const isWeightPR = currentWeight > maxWeightHistory && maxWeightHistory > 0;
const isVolumePR = currentVolume > maxVolumeHistory && maxVolumeHistory > 0;
const isFirstTime = maxWeightHistory === 0; 

let prStatus = "none";
if (isFirstTime) prStatus = "initial";
else if (isWeightPR && isVolumePR) prStatus = "double_pr";
else if (isWeightPR) prStatus = "weight_pr";
else if (isVolumePR) prStatus = "volume_pr";

// 5. Forward everything downstream safely
return {
  ...$json,
  prStatus: prStatus,
  previousMaxWeight: maxWeightHistory,
  previousMaxVolume: maxVolumeHistory
};

