const currentVolume = parseFloat($('Code in JavaScript9').item.json.Volume || 0);
const currentReps = parseInt($('Code in JavaScript9').item.json.Reps || 0);
const currentSets = parseInt($('Code in JavaScript9').item.json.Sets || 0);
const currentCategory = $('Code in JavaScript9').item.json.Category || "unknown";

let maxWeightHistory = 0;
let maxVolumeHistory = 0;
let foundAnyHistory = false;

// 2. Pull PREVIOUS history entries safely from the Google Sheets node output
let historyItems = [];
try {
  historyItems = $items(); 
} catch (e) {
  historyItems = [];
}

// 3. Loop through ALL history entries and match against the current exercise
if (Array.isArray(historyItems) && historyItems.length > 0) {
  for (const item of historyItems) {
    // Check both potential casings from Google Sheets columns
    const pastExercise = item.json.Exercise || item.json.exercise;

    // Only look at rows that match the exercise we are doing right now
    if (pastExercise && String(pastExercise).trim().toLowerCase() === currentExercise.trim().toLowerCase()) {
      foundAnyHistory = true;
      const pastWeight = parseFloat(item.json.Weight || 0);
      const pastVolume = parseFloat(item.json.Volume || 0);

      if (pastWeight > maxWeightHistory) maxWeightHistory = pastWeight;
      if (pastVolume > maxVolumeHistory) maxVolumeHistory = pastVolume;
    }
  }
}

// 4. Determine PR Milestone status accurately
const isWeightPR = currentWeight > maxWeightHistory && maxWeightHistory > 0;
const isVolumePR = currentVolume > maxVolumeHistory && maxVolumeHistory > 0;

// It's only the initial baseline if absolutely no previous history matches this specific movement name
const isFirstTime = !foundAnyHistory; 

let prStatus = "none";
if (isFirstTime) prStatus = "initial";
else if (isWeightPR && isVolumePR) prStatus = "double_pr";
else if (isWeightPR) prStatus = "weight_pr";
else if (isVolumePR) prStatus = "volume_pr";

// 5. Send clean payload out to Google Sheet Appender and Gemini
return {
  Exercise: currentExercise,
  Weight: currentWeight,
  Reps: currentReps,
  Sets: currentSets,
  Volume: currentVolume,
  Category: currentCategory,
  prStatus: prStatus,
  previousMaxWeight: maxWeightHistory,
  previousMaxVolume: maxVolumeHistory
};

