// 1. Grab the raw text block coming from your Gemini AI cleaner node
const rawText = $('HTTP Request7').item.json.candidates[0].content.parts[0].text;

// 2. Clean out any random markdown block formatting if Gemini included it
const cleanJsonString = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

// 3. Convert the text into an actual selectable n8n object
const parsedData = JSON.parse(cleanJsonString);

// 4. Safety Check: If the exercise string contains only numbers (like "9, 20"), give it a safe fallback
let exerciseName = String(parsedData.Exercise || "Unknown Exercise").trim();
if (/^[0-9,\s.]+$/.test(exerciseName)) {
  exerciseName = "Unknown Exercise";
}

// 5. Output clean, predictable data types
return {
  Exercise: exerciseName,
  Weight: parseFloat(parsedData.Weight || 0),
  Reps: parseInt(parsedData.Reps || 0),
  Sets: parseInt(parsedData.Sets || 0),
  Volume: parseFloat(parsedData.Volume || 0),
  Category: parsedData.Category || "unknown"
};

